:root {
	/* Typography */
	--font-family: 'Inter', system-ui, -apple-system, sans-serif;

	--font-weight-normal: 400;
	--font-weight-medium: 500;
	--font-weight-bold: 650; /* Slightly heavier for modern punchy headers */

	--font-size-body: 14px;
	--font-size-label: 14px;
	--font-size-input: 15px;
	--font-size-header: 32px;
	--font-size-subheader: 16px;
	--font-size-paragraph: 15px;

	/* Background */
	--color-background: #0b0f17; /* Deeper, premium midnight canvas */

	/* Cards */
	--color-card-bg: #131a26;
	--color-card-border: rgba(255, 255, 255, 0.06); /* Sophisticated translucent border */
	--color-card-shadow: rgba(0, 0, 0, 0.4);

	/* Text */
	--color-header: #f8fafc;
	--color-header-subtext: #94a3b8;
	--color-label: #cbd5e1;
	--color-html-text: #94a3b8;

	/* Inputs */
	--color-input-bg: #090d14;
	--color-input-border: rgba(255, 255, 255, 0.1);
	--color-input-text: #f8fafc;
	--color-focus-border: #a78bfa;
	--color-focus-ring: rgba(139, 92, 246, 0.25);

	/* Buttons */
	--color-submit-btn-bg-start: #7c3aed;
	--color-submit-btn-bg-end: #6d28d9;
	--color-submit-btn-text: #ffffff;

	/* Links */
	--color-link: #a78bfa;
	--color-html-link: #c084fc;

	/* Validation & States */
	--color-error: #f87171;
	--color-required: #fb923c;

	/* Notice (Softer, less jarring amber tones) */
	--color-test-notice-text: #fde047;
	--color-test-notice-bg: rgba(251, 191, 36, 0.06);
	--color-test-notice-border: rgba(251, 191, 36, 0.2);

	/* Misc */
	--color-clear-button-bg: #334155;

	/* Radius (Smoother, more modern rounding) */
	--border-radius-card: 24px;
	--border-radius-input: 14px;
	--border-radius-clear-btn: 50%;

	/* Layout */
	--container-width: 540px;
	--padding-container-top: 56px;
	--padding-card: 40px; /* More breathing room */
	--padding-form-input: 16px;
	--margin-bottom-card: 28px;

	/* Button */
	--submit-btn-height: 56px;

	/* Effects */
	--box-shadow-card: 0 20px 40px -15px rgba(0, 0, 0, 0.5);
	--opacity-placeholder: 0.5;
	--transition-smooth: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

/* Global Dynamic Elements */

input,
textarea,
select {
	background-color: var(--color-input-bg) !important;
	color: var(--color-input-text) !important;
	border: 1px solid var(--color-input-border) !important;
	border-radius: var(--border-radius-input) !important;
	padding: var(--padding-form-input) !important;
	font-family: var(--font-family);
	font-size: var(--font-size-input);
	transition: var(--transition-smooth) !important;
}

input::placeholder,
textarea::placeholder {
	color: var(--color-header-subtext) !important;
	opacity: var(--opacity-placeholder) !important;
}

input:focus,
textarea:focus,
select:focus {
	outline: none !important;
	border-color: var(--color-focus-border) !important;
	box-shadow: 0 0 0 4px var(--color-focus-ring) !important;
}

button {
	background: linear-gradient(
		135deg,
		var(--color-submit-btn-bg-start),
		var(--color-submit-btn-bg-end)
	) !important;
	color: var(--color-submit-btn-text) !important;
	font-family: var(--font-family);
	font-weight: var(--font-weight-bold);
	border: none !important;
	border-radius: var(--border-radius-input) !important; /* Matches input radius for UI harmony */
	height: var(--submit-btn-height);
	cursor: pointer;
	box-shadow: 0 4px 12px rgba(124, 58, 237, 0.25);
	transition: var(--transition-smooth);
}

button:hover {
	filter: brightness(1.12);
	transform: translateY(-1px);
	box-shadow: 0 6px 20px rgba(124, 58, 237, 0.35);
}

button:active {
	transform: translateY(0);
	filter: brightness(0.95);
}

