const markdown = $input.first().json.text || "";

// Convert escaped newlines into real newlines
const cleanedMarkdown = markdown
    .replace(/\\n/g, '\n')
    .replace(/\\"/g, '"');

function mdToHtml(md) {
    return md

        // Headers
        .replace(/^### (.*$)/gim, '<h3>$1</h3>')
        .replace(/^## (.*$)/gim, '<h2>$1</h2>')
        .replace(/^# (.*$)/gim, '<h1>$1</h1>')

        // Bold
        .replace(/\*\*(.*?)\*\*/gim, '<strong>$1</strong>')

        // Italic
        .replace(/\*(.*?)\*/gim, '<em>$1</em>')

        // Code Blocks
        .replace(/```([\s\S]*?)```/gim, '<pre><code>$1</code></pre>')

        // Inline Code
        .replace(/`([^`]+)`/gim, '<code>$1</code>')

        // Blockquotes
        .replace(/^> (.*$)/gim, '<blockquote>$1</blockquote>')

        // Horizontal Rule
        .replace(/^---$/gim, '<hr>')

        // Images
        .replace(/!\[(.*?)\]\((.*?)\)/gim, '<img alt="$1" src="$2" />')

        // Links
        .replace(/\[(.*?)\]\((.*?)\)/gim, '<a href="$2">$1</a>')

        // Unordered Lists
        .replace(/^\s*-\s+(.*)$/gim, '<li>$1</li>')

        // Ordered Lists
        .replace(/^\s*\d+\.\s+(.*)$/gim, '<li>$1</li>')

        // Wrap list items in <ul>
        .replace(/(<li>.*<\/li>)/gims, '<ul>$1</ul>')

        // Paragraph spacing
        .replace(/\n{2,}/g, '</p><p>')

        // Single line breaks
        .replace(/\n/g, '<br>');
}

const convertedHtml = mdToHtml(cleanedMarkdown);

const html = `
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">

<title>Rendered Markdown</title>

<style>
body{
    font-family: Arial, sans-serif;
    line-height: 1.7;
    max-width: 900px;
    margin: auto;
    padding: 40px;
    color: #222;
    background: #ffffff;
}

h1,h2,h3{
    color: #111;
    margin-top: 30px;
}

p{
    margin-bottom: 16px;
}

pre{
    background: #1e1e1e;
    color: white;
    padding: 16px;
    border-radius: 8px;
    overflow-x: auto;
}

code{
    background: #f4f4f4;
    padding: 2px 6px;
    border-radius: 4px;
}

blockquote{
    border-left: 4px solid #ccc;
    padding-left: 12px;
    color: #555;
    margin: 20px 0;
}

ul{
    padding-left: 20px;
}

li{
    margin-bottom: 8px;
}

a{
    color: #0066cc;
    text-decoration: none;
}

img{
    max-width: 100%;
    border-radius: 8px;
    margin-top: 10px;
}

hr{
    margin: 30px 0;
}
</style>
</head>

<body>
<p>${convertedHtml}</p>
</body>
</html>
`;

return [
  {
    json: {
      html: html,
      markdown: cleanedMarkdown
    }
  }
];
